Perfecto. Sin la variable temporal perderías uno de los valores. Juntemos todo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Cuántos números: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    /* Bubble sort: dos loops anidados */
    for (int i = 0; i < N - 1; i++) {          /* N-1 pasadas */
        for (int j = 0; j < N - 1 - i; j++) {  /* reduce en i cada pasada */
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j]   = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }

    /* Mostrar resultado */
    printf("\nArreglo ordenado:\n");
    for (int i = 0; i < N; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}
```

Resumen de los bounds: externo `i < N-1`, interno `j < N-1-i`. Confundirlos es el error más común en bubble sort.
